const strandsHandler = createHandler(
  ['*', 'agent'],
  async (aiConfig, userInput) => {
    const agent = new Agent({
      model: aiConfig.model.name,
      systemPrompt: aiConfig.instructions ?? '',
    });
    const result = await agent.invoke(userInput ?? '');
    return { output: result.lastMessage?.content ?? result };
  },
);

const result = await config({
  key: '${n}',
  handler: strandsHandler,
}).invoke('What is feature flagging?', { kind: 'user', key: 'user-123' });

